import requests
queries=['"glucose infusion" AND polysulfone dialysis','glucose AND "post-dilution" AND permeability AND dialysis','glucose AND "polysulfone membrane" AND haemodiafiltration','intradialytic glucose AND membrane permeability']
for q in queries:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':30,'retmode':'json'},timeout=20)
 d=r.json()['esearchresult']; ids=d['idlist'];print('\nQUERY',q,'COUNT',d['count'])
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids:
   z=s[i];print(i,z.get('pubdate'),z.get('title'))
